                                            )}
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            </div>
        </div>
    );
}

import { useState, useMemo } from 'react';
import { BookOpen, Search, ChevronDown, ChevronUp, AlertTriangle, CheckCircle2, XCircle, Tag } from 'lucide-react';
import type { PolicyCompliance, PolicyInitiative, PolicyResource, TenantSubscription, RunSnapshot } from '@/types/assessment';
import { displaySubName } from '@/lib/format-sub-name';
import { useShowMore } from '@/hooks/useShowMore';
import { FilterDropdown } from '@/components/ui/FilterDropdown';

interface Props {
    subscriptions: TenantSubscription[];
    subDataMap: Record<string, { latestSnapshot: RunSnapshot | null }>;
    defaultSubId: string;
}

type ViewMode = 'initiatives' | 'policies' | 'resources';

export function PolicyExplorerCard({ subscriptions, subDataMap, defaultSubId }: Props) {
    const [subId, setSubId] = useState(defaultSubId || subscriptions[0]?.id || '');
    const [viewMode, setViewMode] = useState<ViewMode>('initiatives');
    const [searchTerm, setSearchTerm] = useState('');
    const [expandedId, setExpandedId] = useState<string | null>(null);
    const [rgFilter, setRgFilter] = useState('');

    const data: PolicyCompliance | null = subDataMap[subId]?.latestSnapshot?.policyCompliance ?? null;
    const initiatives = data?.initiatives ?? [];

    /* Extract all unique resource groups */
    const resourceGroups = useMemo(() => {
        const set = new Set<string>();
        for (const init of initiatives) {
            for (const r of init.resources) {
                if (r.resourceGroup) set.add(r.resourceGroup);
            }
        }
        return Array.from(set).sort();
    }, [initiatives]);

    /* Extract all unique failing policies across all resources */
    const allPolicies = useMemo(() => {
        const map = new Map<string, { id: string; name: string; description: string; initName: string; count: number; failingResources: PolicyResource[] }>();
        for (const init of initiatives) {
            for (const r of init.resources) {
                for (const fp of r.failingPolicies) {
                    const existing = map.get(fp.id);
                    if (existing) {
                        existing.count++;
                        existing.failingResources.push(r);
                    } else {
                        map.set(fp.id, { ...fp, initName: init.name, count: 1, failingResources: [r] });
                    }
                }
            }
        }
        return Array.from(map.values());
    }, [initiatives]);

    /* Filtered resources */
    const allResources = useMemo(() => {
        const resources: (PolicyResource & { initName: string; initType: string })[] = [];
        for (const init of initiatives) {
            for (const r of init.resources) {
                if (rgFilter && r.resourceGroup !== rgFilter) continue;
                resources.push({ ...r, initName: init.name, initType: init.type });
            }
        }
        if (searchTerm) {
            const lower = searchTerm.toLowerCase();
            return resources.filter(r =>
                r.resourceName.toLowerCase().includes(lower) ||
                r.resourceType.toLowerCase().includes(lower) ||
                r.resourceGroup.toLowerCase().includes(lower)
            );
        }
        return resources;
    }, [initiatives, searchTerm, rgFilter]);

    /* Totals for the top strip */
    const totalInitiatives = initiatives.length;
    const totalCustom = initiatives.filter(i => i.type === 'custom').length;
    const totalBuiltin = initiatives.filter(i => i.type === 'builtin').length;
    const totalResources = allResources.length;
    const nonCompliantResources = allResources.filter(r => r.state !== 'Compliant').length;

    if (!data) {
        return (
            <div className="glass-card gradient-border p-6 flex flex-col items-center justify-center text-muted-foreground h-full min-h-[300px]">
                <BookOpen size={20} className="mr-2 opacity-50" />
                No policy data available
            </div>
        );
    }

    return (
        <div className="glass-card gradient-border scan-line overflow-hidden flex flex-col h-[600px]">
            {/* Header */}
            <div className="p-4 sm:p-5 border-b border-border/50">
                <div className="flex flex-wrap items-center justify-between gap-3">
                    <div className="flex items-center gap-2">
                        <BookOpen size={18} className="text-violet-400" />
                        <h3 className="text-sm font-semibold tracking-tight">Policy Explorer</h3>
                    </div>
                    <div className="flex flex-wrap items-center gap-2">
                        <FilterDropdown
                            value={subId}
                            onValueChange={v => setSubId(v)}
                            options={subscriptions.map(s => ({ value: s.id, label: displaySubName(s) }))}
                            className="w-[140px]"
                        />
                        <FilterDropdown
                            value={rgFilter}
                            onValueChange={v => setRgFilter(v)}
                            options={[
                                { value: '', label: 'All RGs' },
                                ...resourceGroups.map(rg => ({ value: rg, label: rg }))
                            ]}
                            className="w-[130px]"
                        />
                    </div>
                </div>

                {/* View mode tabs */}
                <div className="flex gap-1 mt-3">
                    {(['initiatives', 'policies', 'resources'] as const).map(mode => (
                        <button
                            key={mode}
                            onClick={() => { setViewMode(mode); setExpandedId(null); }}
                            className={`px-3 py-1 rounded-md text-xs font-medium transition-all ${viewMode === mode
                                    ? 'bg-primary text-primary-foreground shadow-sm'
                                    : 'text-muted-foreground hover:bg-muted/50'
                                }`}
                        >
                            {mode === 'initiatives' ? 'Policy Sets' : mode === 'policies' ? 'Failing Policies' : 'Resources'}
                        </button>
                    ))}
                </div>
            </div>

            {/* Top stat strip */}
            <div className="grid grid-cols-2 sm:grid-cols-5 gap-px bg-border/30">
                <MiniStat label="Policy Sets" value={totalInitiatives} />
                <MiniStat label="Built-in" value={totalBuiltin} color="#60a5fa" />
                <MiniStat label="Custom" value={totalCustom} color="#a78bfa" />
                <MiniStat label="Resources" value={totalResources} />
                <MiniStat label="Non-Compliant" value={nonCompliantResources} color="#ef4444" />
            </div>

            {/* Search */}
            <div className="p-3 border-b border-border/30">
                <div className="relative">
                    <Search size={12} className="absolute left-2 top-1/2 -translate-y-1/2 text-muted-foreground" />
                    <input
                        type="text"
                        placeholder={`Search ${viewMode}…`}
                        value={searchTerm}
                        onChange={e => setSearchTerm(e.target.value)}
                        className="w-full h-7 rounded-md border border-input bg-background pl-6 pr-2 text-xs ring-offset-background focus:outline-none focus:ring-1 focus:ring-ring"
                    />
                </div>
            </div>

            {/* Content — flex-1 fills remaining height */}
            <div className="p-3 flex-1 min-h-0 overflow-y-auto space-y-1.5">
                {viewMode === 'initiatives' && <InitiativesList
                    initiatives={initiatives}
                    searchTerm={searchTerm}
                    expandedId={expandedId}
                    setExpandedId={setExpandedId}
                />}
                {viewMode === 'policies' && <PoliciesList
                    policies={allPolicies}
                    searchTerm={searchTerm}
                    expandedId={expandedId}
                    setExpandedId={setExpandedId}
                />}
                {viewMode === 'resources' && <ResourcesList
                    resources={allResources}
                    searchTerm={searchTerm}
                />}
            </div>
        </div>
    );
}

/* ─── Sub-Components ──────────────────────────────────────────────── */

function ShowMoreButton({ remaining, onClick }: { remaining: number; onClick: () => void }) {
    return (
        <button
            onClick={onClick}
            className="w-full mt-2 py-1.5 rounded-md text-xs font-medium text-primary hover:bg-primary/10 border border-primary/20 transition-all"
        >
            Show {Math.min(remaining, 50)} more ({remaining} remaining)
        </button>
    );
}

function MiniStat({ label, value, color }: { label: string; value: number; color?: string }) {
    return (
        <div className="bg-card/40 p-2 text-center">
            <p className="stat-glow text-lg font-bold" style={{ color: color ?? 'inherit' }}>{value}</p>
            <p className="text-[10px] text-muted-foreground">{label}</p>
        </div>
    );
}

function InitiativesList({ initiatives, searchTerm, expandedId, setExpandedId }: {
    initiatives: PolicyInitiative[];
    searchTerm: string;
    expandedId: string | null;
    setExpandedId: (id: string | null) => void;
}) {
    const filtered = useMemo(() => {
        if (!searchTerm) return initiatives;
        const lower = searchTerm.toLowerCase();
        return initiatives.filter(i => i.name.toLowerCase().includes(lower));
    }, [initiatives, searchTerm]);

    if (filtered.length === 0) {
        return <p className="text-center text-xs text-muted-foreground py-4">No policy sets found.</p>;
    }

    return (
        <>
            {filtered.map(init => {
                const pct = init.totalPolicies > 0 ? Math.round((init.compliantCount / init.totalPolicies) * 100) : 0;
                const isExpanded = expandedId === init.id;
                const nonCompliant = init.resources.filter(r => r.state !== 'Compliant');
                return (
                    <div key={init.id} className="rounded-lg border border-border/50 bg-card/30 hover:bg-card/60 transition-all">
                        <button
                            onClick={() => setExpandedId(isExpanded ? null : init.id)}
                            className="w-full p-2.5 flex items-center gap-3 text-left"
                        >
                            <Tag size={14} className={init.type === 'custom' ? 'text-violet-400' : 'text-sky-400'} />
                            <div className="flex-1 min-w-0">
                                <div className="flex items-center gap-1.5">
                                    <span className="text-xs font-medium truncate">{init.name}</span>
                                    <span className="flex-shrink-0 rounded px-1 py-px text-[9px] font-medium"
                                        style={{
                                            background: init.type === 'custom' ? '#a78bfa18' : '#60a5fa18',
                                            color: init.type === 'custom' ? '#a78bfa' : '#60a5fa',
                                        }}
                                    >
                                        {init.type === 'custom' ? 'Custom' : 'Built-in'}
                                    </span>
                                </div>
                                <div className="flex items-center gap-2 mt-1">
                                    <div className="flex-1 h-1 rounded-full bg-muted/40 overflow-hidden max-w-[160px]">
                                        <div className="h-full rounded-full" style={{
                                            width: `${pct}%`,
                                            background: pct >= 80 ? '#22c55e' : pct >= 60 ? '#eab308' : '#ef4444',
                                        }} />
                                    </div>
                                    <span className="text-[10px] text-muted-foreground">{init.compliantCount}/{init.totalPolicies}</span>
                                </div>
                            </div>
                            {isExpanded ? <ChevronUp size={12} className="text-muted-foreground" /> : <ChevronDown size={12} className="text-muted-foreground" />}
                        </button>
                        <div className="expand-panel" data-open={isExpanded ? 'true' : 'false'}>
                            <div className="px-2.5 pb-2.5 pt-0 border-t border-border/30">
                                <div className="grid grid-cols-3 gap-2 py-2 text-center">
                                    <div>
                                        <p className="text-xs font-bold text-green-500">{init.compliantCount}</p>
                                        <p className="text-[9px] text-muted-foreground">Compliant</p>
                                    </div>
                                    <div>
                                        <p className="text-xs font-bold text-red-400">{init.nonCompliantCount}</p>
                                        <p className="text-[9px] text-muted-foreground">Non-Compliant</p>
                                    </div>
                                    <div>
                                        <p className="text-xs font-bold text-yellow-500">{init.exemptCount}</p>
                                        <p className="text-[9px] text-muted-foreground">Exempt</p>
                                    </div>
                                </div>
                                {/* Resource listing — show up to 20 */}
                                <ExpandableResourceList resources={nonCompliant} maxInitial={20} />
                            </div>
                        </div>
                    </div>
                );
            })}
        </>
    );
}

function ExpandableResourceList({ resources, maxInitial = 20 }: { resources: PolicyResource[]; maxInitial?: number }) {
    const { limit, showMore, hasMore } = useShowMore(maxInitial);
    const visible = resources.slice(0, limit);

    if (resources.length === 0) return null;

    return (
        <div>
            {visible.map(r => (
                <div key={r.resourceId} className="flex items-center gap-1.5 text-[10px] py-0.5">
                    <XCircle size={10} className="text-red-400 flex-shrink-0" />
                    <span className="truncate text-muted-foreground">{r.resourceName}</span>
                    <span className="text-muted-foreground/50">·</span>
                    <span className="truncate text-muted-foreground/70">{r.resourceGroup}</span>
                </div>
            ))}
            {hasMore(resources.length) && (
                <ShowMoreButton remaining={resources.length - limit} onClick={showMore} />
            )}
        </div>
    );
}

function PoliciesList({ policies, searchTerm, expandedId, setExpandedId }: {
    policies: { id: string; name: string; description: string; initName: string; count: number; failingResources: PolicyResource[] }[];
    searchTerm: string;
    expandedId: string | null;
    setExpandedId: (id: string | null) => void;
}) {
    const filtered = useMemo(() => {
        if (!searchTerm) return policies;
        const lower = searchTerm.toLowerCase();
        return policies.filter(p => p.name.toLowerCase().includes(lower) || p.description.toLowerCase().includes(lower));
    }, [policies, searchTerm]);

    if (filtered.length === 0) {
        return <p className="text-center text-xs text-muted-foreground py-4">
            {policies.length === 0 ? 'All policies are passing — no failing policies found.' : 'No policies match the search.'}
        </p>;
    }

    return (
        <>
            {filtered.map(pol => {
                const isExpanded = expandedId === pol.id;
                return (
                    <div key={pol.id} className="rounded-lg border border-border/50 bg-card/30 hover:bg-card/60 transition-all">
                        <button
                            onClick={() => setExpandedId(isExpanded ? null : pol.id)}
                            className="w-full p-2.5 flex items-center gap-3 text-left"
                        >
                            <AlertTriangle size={14} className="text-red-400 flex-shrink-0" />
                            <div className="flex-1 min-w-0">
                                <span className="text-xs font-medium truncate block">{pol.name}</span>
                                <span className="text-[10px] text-muted-foreground truncate block">{pol.description}</span>
                            </div>
                            <span className="flex-shrink-0 rounded-full px-1.5 py-0.5 text-[10px] font-bold bg-red-500/10 text-red-400 border border-red-500/20">
                                {pol.count}
                            </span>
                            {isExpanded ? <ChevronUp size={12} className="text-muted-foreground" /> : <ChevronDown size={12} className="text-muted-foreground" />}
                        </button>
                        <div className="expand-panel" data-open={isExpanded ? 'true' : 'false'}>
                            <div className="px-2.5 pb-2.5 border-t border-border/30 pt-2">
                                <p className="text-[10px] text-muted-foreground mb-1">
                                    From: <span className="font-medium text-foreground">{pol.initName}</span>
                                </p>
                                {/* Show up to 20 failing resources with Show More */}
                                <ExpandableResourceList resources={pol.failingResources} maxInitial={20} />
                            </div>
                        </div>
                    </div>
                );
            })}
        </>
    );
}

function ResourcesList({ resources, searchTerm }: {
    resources: (PolicyResource & { initName: string; initType: string })[];
    searchTerm: string;
}) {
    const { limit, showMore, hasMore } = useShowMore(50);

    const filtered = useMemo(() => {
        if (!searchTerm) return resources;
        const lower = searchTerm.toLowerCase();
        return resources.filter(r =>
            r.resourceName.toLowerCase().includes(lower) ||
            r.resourceType.toLowerCase().includes(lower) ||
            r.resourceGroup.toLowerCase().includes(lower)
        );
    }, [resources, searchTerm]);

    if (filtered.length === 0) {
        return <p className="text-center text-xs text-muted-foreground py-4">No resources found.</p>;
    }

    const visible = filtered.slice(0, limit);

    return (
        <div className="space-y-0.5">
            {visible.map(r => (
                <div key={r.resourceId} className="flex items-center gap-2 p-2 rounded-md hover:bg-muted/30 transition-all text-xs">
                    {r.state === 'Compliant'
                        ? <CheckCircle2 size={13} className="text-green-500 flex-shrink-0" />
                        : <XCircle size={13} className="text-red-400 flex-shrink-0" />
                    }
                    <div className="flex-1 min-w-0">
                        <span className="font-medium truncate block">{r.resourceName}</span>
                        <span className="text-[10px] text-muted-foreground truncate block">{r.resourceType}</span>
                    </div>
                    <span className="hidden sm:inline text-[10px] text-muted-foreground truncate max-w-[100px]">{r.resourceGroup}</span>
                    <span className="text-[10px] text-muted-foreground truncate max-w-[80px]">{r.initName}</span>
                </div>
            ))}
            {hasMore(filtered.length) && (
                <ShowMoreButton remaining={filtered.length - limit} onClick={showMore} />
            )}
        </div>
    );
}

import { useState, useMemo } from 'react';
import { displaySubName } from '@/lib/format-sub-name';
import { useShowMore } from '@/hooks/useShowMore';
import {
    BarChart, Bar, XAxis, YAxis, CartesianGrid, ResponsiveContainer, Tooltip, Cell,
} from 'recharts';
import { ShieldAlert, Search, ChevronDown, ChevronUp, Zap, ExternalLink } from 'lucide-react';
import type { DefenderRecs, DefenderRecommendation, Severity, TenantSubscription, RunSnapshot } from '@/types/assessment';
import { FilterDropdown } from '@/components/ui/FilterDropdown';

interface Props {
    subscriptions: TenantSubscription[];
    subDataMap: Record<string, { latestSnapshot: RunSnapshot | null }>;
    defaultSubId: string;
}

const SEV_CONFIG: Record<Severity, { color: string; label: string; order: number }> = {
    critical: { color: '#ef4444', label: 'Critical', order: 0 },
    high: { color: '#f97316', label: 'High', order: 1 },
    medium: { color: '#eab308', label: 'Medium', order: 2 },
    low: { color: '#22c55e', label: 'Low', order: 3 },
};

export function RecommendationsCard({ subscriptions, subDataMap, defaultSubId }: Props) {
    const [subId, setSubId] = useState(defaultSubId || subscriptions[0]?.id || '');
    const [sevFilter, setSevFilter] = useState<Severity | ''>('');
    const [searchTerm, setSearchTerm] = useState('');
    const [expandedId, setExpandedId] = useState<string | null>(null);
    const { limit, showMore, hasMore } = useShowMore(25);

    const data: DefenderRecs | null = subDataMap[subId]?.latestSnapshot?.defenderRecs ?? null;
    const recs = data?.recommendations ?? [];

    /* Filtered recommendations */
    const filtered = useMemo(() => {
        let list = recs;
        if (sevFilter) list = list.filter(r => r.severity === sevFilter);
        if (searchTerm) {
            const lower = searchTerm.toLowerCase();
            list = list.filter(r =>
                r.name.toLowerCase().includes(lower) ||
                r.description.toLowerCase().includes(lower) ||
                r.category.toLowerCase().includes(lower)
            );
        }
        return list.sort((a, b) => SEV_CONFIG[a.severity].order - SEV_CONFIG[b.severity].order);
    }, [recs, sevFilter, searchTerm]);

    /* Chart data — severity counts */
    const sevCounts = useMemo(() => {
        const counts: Record<Severity, number> = { critical: 0, high: 0, medium: 0, low: 0 };
        for (const r of recs) counts[r.severity]++;
        return (['critical', 'high', 'medium', 'low'] as Severity[]).map(s => ({
            name: SEV_CONFIG[s].label,
            value: counts[s],
            color: SEV_CONFIG[s].color,
            severity: s,
        }));
    }, [recs]);

    /* Stats */
    const attackPathCount = recs.filter(r => r.hasAttackPath).length;
    const totalAffected = recs.reduce((sum, r) => sum + r.resourceCount, 0);

    if (!data) {
        return (
            <div className="glass-card gradient-border p-6 flex flex-col items-center justify-center text-muted-foreground h-48 gap-3">
                <ShieldAlert size={20} className="opacity-50" />
                No recommendation data
                <FilterDropdown
                    value={subId}
                    onValueChange={v => setSubId(v)}
                    options={subscriptions.map(s => ({ value: s.id, label: displaySubName(s) }))}
                    className="w-[200px]"
                />
            </div>
        );
    }

    if (data.recommendations.length === 0) {
        return (
            <div className="glass-card gradient-border p-6 flex flex-col items-center justify-center h-48 gap-3 text-center">
                <ShieldAlert size={32} className="text-emerald-500/40" />
                <h3 className="text-sm font-semibold text-foreground">No Defender Recommendations</h3>
                <p className="text-xs text-muted-foreground max-w-[300px]">
                    No open recommendations exist for this subscription. Ensure Defender plans are enabled.
                </p>
                <FilterDropdown
                    value={subId}
                    onValueChange={v => setSubId(v)}
                    options={subscriptions.map(s => ({ value: s.id, label: displaySubName(s) }))}
                    className="w-[200px]"
                />
            </div>
        );
    }

    return (
        <div className="glass-card gradient-border scan-line overflow-hidden">
            {/* Header */}
            <div className="p-4 sm:p-5 border-b border-border/50">
                <div className="flex flex-wrap items-center justify-between gap-3">
                    <div className="flex items-center gap-2">
                        <ShieldAlert size={18} className="text-orange-400" />
                        <h3 className="text-sm font-semibold tracking-tight">Defender Recommendations</h3>
                    </div>
                    <div className="flex flex-wrap items-center gap-2">
                        <FilterDropdown
                            value={subId}
                            onValueChange={v => setSubId(v)}
                            options={subscriptions.map(s => ({ value: s.id, label: displaySubName(s) }))}
                            className="w-[140px]"
                        />
                        <FilterDropdown
                            value={sevFilter}
                            onValueChange={v => setSevFilter(v as Severity | '')}
                            options={[
                                { value: '', label: 'All Severities' },
                                ...Object.entries(SEV_CONFIG).map(([k, v]) => ({ value: k, label: v.label }))
                            ]}
                            className="w-[140px]"
                        />
                    </div>
                </div>
            </div>

            <div className="p-4 sm:p-5">
                <div className="grid grid-cols-1 lg:grid-cols-5 gap-5">
                    {/* Severity bar chart */}
                    <div className="lg:col-span-2">
                        <p className="text-xs text-muted-foreground mb-2 font-medium">By Severity</p>
                        <div className="h-36">
                            <ResponsiveContainer width="100%" height="100%">
                                <BarChart data={sevCounts} margin={{ left: 0, right: 8, top: 4, bottom: 4 }}>
                                    <CartesianGrid strokeDasharray="3 3" className="opacity-20" />
                                    <XAxis dataKey="name" tick={{ fontSize: 10 }} className="text-muted-foreground" />
                                    <YAxis allowDecimals={false} tick={{ fontSize: 10 }} className="text-muted-foreground" width={28} />
                                    <Tooltip
                                        contentStyle={{
                                            borderRadius: '0.5rem',
                                            border: '1px solid hsl(var(--border))',
                                            background: 'hsl(var(--popover))',
                                            color: 'hsl(var(--popover-foreground))',
                                            fontSize: '0.75rem',
                                        }}
                                    />
                                    <Bar
                                        dataKey="value"
                                        radius={[4, 4, 0, 0]}
                                        cursor="pointer"
                                        onClick={(entry: { severity: Severity }) => setSevFilter(sevFilter === entry.severity ? '' : entry.severity)}
                                    >
                                        {sevCounts.map((entry, i) => (
                                            <Cell
                                                key={i}
                                                fill={entry.color}
                                                opacity={sevFilter && sevFilter !== entry.severity ? 0.3 : 1}
                                            />
                                        ))}
                                    </Bar>
                                </BarChart>
                            </ResponsiveContainer>
                        </div>
                        {/* Quick stats */}
                        <div className="flex flex-wrap gap-3 mt-3 justify-center">
                            <span className="inline-flex items-center gap-1 text-[10px] text-muted-foreground">
                                <span className="font-bold text-foreground">{recs.length}</span> total
                            </span>
                            <span className="inline-flex items-center gap-1 text-[10px] text-muted-foreground">
                                <span className="font-bold text-foreground">{totalAffected}</span> resources
                            </span>
                            {attackPathCount > 0 && (
                                <span className="inline-flex items-center gap-1 text-[10px] text-red-400 font-medium">
                                    <Zap size={10} />{attackPathCount} attack paths
                                </span>
                            )}
                        </div>
                    </div>

                    {/* Recommendations list */}
                    <div className="lg:col-span-3">
                        <div className="relative mb-2">
                            <Search size={12} className="absolute left-2 top-1/2 -translate-y-1/2 text-muted-foreground" />
                            <input
                                type="text"
                                placeholder="Search recommendations…"
                                value={searchTerm}
                                onChange={e => setSearchTerm(e.target.value)}
                                className="w-full h-7 rounded-md border border-input bg-background pl-6 pr-2 text-xs focus:outline-none focus:ring-1 focus:ring-ring"
                            />
                        </div>
                        <div className="space-y-1.5 max-h-[260px] overflow-y-auto pr-1">
                            {filtered.length === 0 && (
                                <p className="text-center text-xs text-muted-foreground py-4">No recommendations match.</p>
                            )}
                            {filtered.slice(0, limit).map(rec => {
                                const isExpanded = expandedId === rec.id;
                                const sev = SEV_CONFIG[rec.severity];
                                return (
                                    <RecItem key={rec.id} rec={rec} sev={sev} isExpanded={isExpanded}
                                        onToggle={() => setExpandedId(isExpanded ? null : rec.id)} />
                                );
                            })}
                            {hasMore(filtered.length) && (
                                <button
                                    onClick={() => showMore()}
                                    className="w-full mt-2 py-2 rounded-md text-xs font-medium text-primary hover:bg-primary/10 border border-primary/20 transition-all"
                                >
                                    Show more ({filtered.length - limit} remaining)
                                </button>
                            )}
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}

function RecItem({ rec, sev, isExpanded, onToggle }: {
    rec: DefenderRecommendation;
    sev: { color: string; label: string };
    isExpanded: boolean;
    onToggle: () => void;
}) {
    return (
        <div className="rounded-lg border border-border/50 bg-card/30 hover:bg-card/60 transition-all">
            <button onClick={onToggle} className="w-full p-2.5 flex items-center gap-2.5 text-left">
                <span
                    className="inline-block w-2 h-2 rounded-full flex-shrink-0"
                    style={{ background: sev.color, boxShadow: `0 0 6px ${sev.color}50` }}
                />
                <div className="flex-1 min-w-0">
                    <span className="text-xs font-medium truncate block">{rec.name}</span>
                    <span className="text-[10px] text-muted-foreground truncate block">{rec.description}</span>
                </div>
                <div className="flex items-center gap-2 flex-shrink-0">
                    {rec.hasAttackPath && (
                        <span className="flex items-center gap-0.5 text-[9px] font-medium text-red-400 bg-red-500/10 rounded-full px-1.5 py-0.5 border border-red-500/20">
                            <Zap size={8} /> Attack Path
                        </span>
                    )}
                    <span className="text-[10px] text-muted-foreground">{rec.resourceCount} res.</span>
                    {isExpanded ? <ChevronUp size={12} className="text-muted-foreground" /> : <ChevronDown size={12} className="text-muted-foreground" />}
                </div>
            </button>
            <div className="expand-panel" data-open={isExpanded ? 'true' : 'false'}>
                <div className="px-2.5 pb-2.5 border-t border-border/30 pt-2 space-y-2">
                    {/* Metadata */}
                    <div className="grid grid-cols-2 gap-2 text-[10px]">
                        <div>
                            <span className="text-muted-foreground">Severity:</span>{' '}
                            <span className="font-medium" style={{ color: sev.color }}>{sev.label}</span>
                        </div>
                        <div>
                            <span className="text-muted-foreground">Category:</span>{' '}
                            <span className="font-medium">{rec.category}</span>
                        </div>
                    </div>
                    {/* Remediation */}
                    <div className="text-[10px]">
                        <span className="text-muted-foreground">Remediation:</span>{' '}
                        <span className="text-foreground">{rec.remediation}</span>
                    </div>
                    <AffectedResources resources={rec.affectedResources} sev={sev} />
                    {/* Learn more */}
                    {rec.learnMoreUrl && (
                        <a
                            href={rec.learnMoreUrl}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="inline-flex items-center gap-1 text-[10px] text-sky-500 hover:text-sky-400 transition-colors"
                        >
                            <ExternalLink size={10} /> Learn more
                        </a>
                    )}
                </div>
            </div>
        </div>
    );
}

function AffectedResources({ resources, sev }: { resources: NonNullable<DefenderRecs['recommendations'][0]>['affectedResources'], sev: any }) {
    const { limit, showMore, hasMore } = useShowMore(10);
    const visible = resources.slice(0, limit);

    return (
        <div className="space-y-0.5">
            <p className="text-[10px] text-muted-foreground font-medium">Affected Resources:</p>
            {visible.map(ar => (
                <div key={ar.id} className="flex items-center gap-1.5 text-[10px]">
                    <span className="w-1.5 h-1.5 rounded-full flex-shrink-0" style={{ background: sev.color }} />
                    <span className="truncate">{ar.name}</span>
                    <span className="text-muted-foreground/50">·</span>
                    <span className="text-muted-foreground/70 truncate">{ar.type.split('/').pop()}</span>
                </div>
            ))}
            {hasMore(resources.length) && (
                <button
                    onClick={(e) => { e.stopPropagation(); showMore(); }}
                    className="mt-1 w-full text-left text-[10px] text-primary hover:underline"
                >
                    + Show {Math.min(resources.length - limit, 10)} more ({resources.length - limit} left)
                </button>
            )}
        </div>
    );
}

import { useMemo } from 'react';
import { Shield, CheckCircle2, XCircle } from 'lucide-react';
import type { ZeroTrust } from '@/types/assessment';

interface Props {
    data: ZeroTrust | null;
}

const PILLAR_COLORS: Record<string, string> = {
    Identity: '#818cf8',
    Devices: '#f472b6',
    Apps: '#34d399',
    Network: '#60a5fa',
    Infrastructure: '#fbbf24',
    Data: '#a78bfa',
};

export function SecurityScoreGauge({ data }: Props) {
    const score = data?.overallScore ?? 0;
    const pillars = data?.pillars ?? [];
    const checks = data?.checks ?? [];

    const totalPassed = useMemo(() => checks.filter(c => c.status === 'passed').length, [checks]);
    const totalFailed = useMemo(() => checks.filter(c => c.status === 'failed').length, [checks]);

    /* Arc constants */
    const radius = 72;
    const stroke = 10;
    const circumference = 2 * Math.PI * radius;
    const offset = circumference - (score / 100) * circumference;

    /* Score color gradient */
    const scoreColor = score >= 80 ? '#22c55e' : score >= 60 ? '#eab308' : '#ef4444';

    if (!data) return null;

    return (
        <div className="glass-card gradient-border scan-line p-5 sm:p-6 mb-6">
            <div className="flex flex-col lg:flex-row items-center gap-6 lg:gap-10">
                {/* Gauge */}
                <div className="relative flex-shrink-0">
                    <svg
                        width={200}
                        height={200}
                        viewBox="0 0 200 200"
                        className="drop-shadow-lg"
                    >
                        {/* Background circle */}
                        <circle
                            cx="100"
                            cy="100"
                            r={radius}
                            fill="none"
                            stroke="currentColor"
                            strokeWidth={stroke}
                            className="text-muted/30"
                        />
                        {/* Score arc */}
                        <circle
                            cx="100"
                            cy="100"
                            r={radius}
                            fill="none"
                            stroke={scoreColor}
                            strokeWidth={stroke}
                            strokeLinecap="round"
                            strokeDasharray={circumference}
                            strokeDashoffset={offset}
                            className="progress-ring-animated"
                            style={{
                                transform: 'rotate(-90deg)',
                                transformOrigin: '100px 100px',
                                filter: `drop-shadow(0 0 8px ${scoreColor}50)`,
                            }}
                        />
                        {/* Center text */}
                        <text
                            x="100"
                            y="92"
                            textAnchor="middle"
                            className="fill-foreground font-bold"
                            style={{ fontSize: '2.2rem' }}
                        >
                            {score}
                        </text>
                        <text
                            x="100"
                            y="118"
                            textAnchor="middle"
                            className="fill-muted-foreground"
                            style={{ fontSize: '0.75rem' }}
                        >
                            Overall Score
                        </text>
                    </svg>
                    <Shield
                        className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 opacity-[0.04] pointer-events-none"
                        size={130}
                    />
                </div>

                {/* Info */}
                <div className="flex-1 min-w-0 text-center lg:text-left">
                    <h2 className="text-lg sm:text-xl font-semibold tracking-tight mb-1 flex items-center gap-2 justify-center lg:justify-start">
                        <Shield size={20} className="text-sky-400" />
                        Zero Trust Posture
                    </h2>
                    <p className="text-xs text-muted-foreground mb-4">{data.tenantName} — {data.runDate}</p>

                    {/* Quick stats */}
                    <div className="flex items-center gap-4 justify-center lg:justify-start mb-4">
                        <div className="flex items-center gap-1.5 text-sm">
                            <CheckCircle2 size={15} className="text-green-500" />
                            <span className="stat-glow font-semibold text-green-500">{totalPassed}</span>
                            <span className="text-muted-foreground">passed</span>
                        </div>
                        <div className="flex items-center gap-1.5 text-sm">
                            <XCircle size={15} className="text-red-400" />
                            <span className="stat-glow font-semibold text-red-400">{totalFailed}</span>
                            <span className="text-muted-foreground">failed</span>
                        </div>
                    </div>

                    {/* Pillar chips */}
                    <div className="flex flex-wrap gap-2 justify-center lg:justify-start">
                        {pillars.map((p) => {
                            const color = PILLAR_COLORS[p.name] ?? '#94a3b8';
                            return (
                                <span
                                    key={p.name}
                                    className="inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-xs font-medium border transition-all hover:scale-105"
                                    style={{
                                        borderColor: `${color}40`,
                                        background: `${color}12`,
                                        color,
                                    }}
                                >
                                    <span
                                        className="inline-block w-2 h-2 rounded-full"
                                        style={{ background: color }}
                                    />
                                    {p.name}
                                    <span className="font-bold">{p.score}%</span>
                                </span>
                            );
                        })}
                    </div>
                </div>

                {/* Pillar mini bars */}
                <div className="hidden xl:flex flex-col gap-2 w-48 flex-shrink-0">
                    {pillars.map((p) => {
                        const color = PILLAR_COLORS[p.name] ?? '#94a3b8';
                        return (
                            <div key={p.name} className="flex items-center gap-2 text-xs">
                                <span className="w-20 truncate text-muted-foreground">{p.name}</span>
                                <div className="flex-1 h-2 rounded-full bg-muted/40 overflow-hidden">
                                    <div
                                        className="h-full rounded-full transition-all duration-700"
                                        style={{
                                            width: `${p.score}%`,
                                            background: color,
                                            boxShadow: `0 0 6px ${color}50`,
                                        }}
                                    />
                                </div>
                                <span className="w-8 text-right font-semibold" style={{ color }}>{p.score}</span>
                            </div>
                        );
                    })}
                </div>
            </div>
        </div>
    );
}

